22	/**
23	 * Thrown when a request to create an owner would exceed the number of owners that may be registered in
24	 * a single day - that is, the maximum permitted number of owners have already been created today (by
25	 * {@code registrationDate}). Unlike the {@link DuplicateOwnerException} family this is a rate limit
26	 * rather than a uniqueness collision, so it is reported to the client as a {@code 429 Too Many
27	 * Requests}. Carries the offending date and the client-facing detail so the
28	 * {@link ExceptionControllerAdvice} can render the response.
29	 */
30	public class OwnerDailyRegistrationLimitException extends RuntimeException {
31	
32	    private static final String DETAIL = "The maximum number of owners for today has already been reached";
33	
34	    private final LocalDate date;
35	
36	    public OwnerDailyRegistrationLimitException(LocalDate date) {
37	        super("Daily owner registration limit reached for: " + date);
38	        this.date = date;
39	    }
40	
41	    public LocalDate getDate() {
42	        return this.date;
43	    }
44	
45	    public String getDetail() {
46	        return DETAIL;
47	    }
48	
49	    public List<String> getErrorFields() {
50	        return List.of("registrationDate");
51	    }
52	}
